            rect = surface.get_rect(center=(x, y))
        elif right:
            rect = surface.get_rect()
            rect.right = x
            rect.top = y
        else:
            rect = surface.get_rect(topleft=(x, y))
        self.screen.blit(surface, rect)
        return font.get_height()

